    7'd103,
    7'd104,
    7'd105,
    7'd106,
    7'd107,
    7'd108
};


//Driving Stimulus to DUT
initial begin
    $dumpfile("hex_to_rtl_top_tb.vcd");
    $dumpvars(0, hex_to_rtl_top_tb);
    rst = 1;
    data_in = '0;
    data_in_valid = '0;
    path_id_out_ready = 1'b1;
    #20;
    rst = 0;
    data_in_sop = '0;
    data_in_eop = '0;

    // Send packets
    for (int ii = 0; ii < 108; ii = ii + 1) begin

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b1;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][895 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][831 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][767 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][703 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][639 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][575 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][511 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][447 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][383 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][319 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][255 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][191 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;
      data_in = stimulus_vec[ii][127 -: 64];

      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = 1'b0;
      data_in_eop = 1'b1;
      data_in = stimulus_vec[ii][63 -: 64];

      @(posedge clk);
      data_in  = '0;
      data_in_valid = 1'b0;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;

      // Idle cycles between packets -- generous enough to drain the
      // comparison/lookup pipeline before the next SOP, so a new packet
      // can't reset flit_counter mid-flight and corrupt path_id_out.
      repeat ($urandom_range(16, 19)) @(posedge clk);
    end

    // Finish after some time
    #100;
    $finish;
end

// DUT instantiation
hex_to_rtl_top
dut (
    .clk            (clk),
    .rst            (rst),
    .data_in        (data_in),
    .data_in_sop    (data_in_sop),
    .data_in_eop    (data_in_eop),
    .data_in_valid  (data_in_valid),
    .data_in_ready  (data_in_ready),
    .path_id_out_ready (path_id_out_ready),
    .path_id_out    (path_id_out),
    .path_id_out_valid (path_id_out_valid)
);

// Scoreboard
logic [7-1:0] dut_q[$];

//store the data from dut into dut_q
always_ff @ (posedge clk) begin
    if (path_id_out_valid) begin
        dut_q.push_back(path_id_out);
    end
end

always_ff @ (posedge clk) begin
    if (dut_q.size() > 0 && golden_q.size() > 0) begin
        logic [7-1:0] act = dut_q.pop_front();
        logic [7-1:0] exp = golden_q.pop_front();

        if (act != exp) begin
            $display ("[%0t] MISMATCH: Got %0h, Expected %0h", $time, act, exp);
        end else begin
            $display ("[%0t] MATCH: %0h", $time, act);
        end
    end
end

endmodule: hex_to_rtl_top_tb
